// Normalizuje surowe pola z wezla HTML do kontraktu z docs/n8n-spec.md.
// Jedno wejscie = jedna ksiazka.
const ws = (s) => (s || '').split(/\s+/).filter(Boolean).join(' ');

// Wezel HTML z returnValue "text" WKLEJA adresy z <a href> jako [https://...].
// Zdejmujemy je z KAZDEGO pola tekstowego, bo katalog moze zlinkowac dowolne z nich.
const unlink = (s) => ws(s).replace(/\s*\[\s*https?:\/\/[^\]]*\]/g, '');

const esc = (s) => unlink(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Telegram w trybie HTML wymaga ucieczki & < > TAKZE wewnatrz href.
const escAttr = (s) => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const out = [];
for (const item of $input.all()) {
  const j = item.json;

  const m = /location\.href='([^']+)'/.exec(j.onclick || '');
  const link = m ? m[1] : null;

  const src = (j.imgSrc || '').trim();
  const img = src ? (src.startsWith('//') ? 'https:' + src : src) : null;

  const header = unlink(j.header);
  const dm = /(\d{2}\.\d{2}\.\d{4})/.exec(header);
  const addedOn = dm ? dm[1] : header.split(' ')[2] || null;

  const available = !!(j.availableRaw && String(j.availableRaw).trim().length);

  const title = unlink(j.title);
  const publisher = unlink(j.publisher);

  // Kolejka oczekujacych: .opacit-queue, tekst "Dlugosc kolejki oczekujacych: N".
  // POLE OPCJONALNE - na stronie ma je 15 z 20 ksiazek, egzemplarze dostepne go nie maja.
  // Gdy go nie ma, wiadomosc ma wygladac dokladnie jak wczesniej: bez separatora,
  // bez naglowka, bez "brak danych".
  const queue = unlink(j.queueRaw);

  let message =
    '\u{1F195} <b>Nowa książka dodana ' + esc(addedOn || '') + '</b>\n\n' +
    '<b><a href="' + escAttr(link || '') + '">' + esc(title) + '</a></b>\n' +
    esc(publisher) + '\n' +
    'Status: ' + (available ? '✅' : '❌');

  if (queue) {
    message += '\n\n' + esc(queue);
  }

  // STRAZNIK 1: surowy adres, ktory ominal unlink().
  if (/\[\s*https?:\/\//.test(message)) {
    throw new Error('W zlozonej wiadomosci zostal surowy adres w nawiasach kwadratowych. Ktores pole tekstowe omija unlink(). Ksiazka: ' + title);
  }

  // STRAZNIK 2: slad po pustym polu opcjonalnym. Wychodzi dopiero na ksiazce
  // BEZ kolejki, czyli na produkcji - dlatego przebieg ma tu stanac.
  if (/\n\s*$/.test(message)) {
    throw new Error('Wiadomosc konczy sie pusta linia - puste pole opcjonalne zostawilo separator. Ksiazka: ' + title);
  }
  if (/\n[^\S\n]*\n[^\S\n]*\n/.test(message)) {
    throw new Error('Wiadomosc ma dwie puste linie pod rzad. Ksiazka: ' + title);
  }

  if (!link) { continue; }
  out.push({ json: { title, publisher, link, img, added_on: addedOn, available, queue: queue || null, message } });
}
return out;

