// Records a coverless announcement so a later run can swap the placeholder for the real cover.
// The catalog link is read back from the Telegram response, NOT from item pairing, because this
// node also receives items from the error output of "Telegram: z okladka".
// The post is now a PHOTO, so the link lives in caption_entities; entities is kept as a fallback
// for anything still arriving as plain text.
const sd = $getWorkflowStaticData('global');
if (!sd.pendingCovers) { sd.pendingCovers = {}; }

for (const item of $input.all()) {
  const res = item.json.result;
  if (!res || !res.message_id) { continue; }
  const ents = res.caption_entities || res.entities || [];
  const ent = ents.find((e) => e.type === 'text_link' && /katalog\.wbp\.poznan\.pl/.test(e.url || ''));
  if (!ent) { continue; }
  sd.pendingCovers[ent.url] = {
    message_id: res.message_id,
    chat_id: (res.chat || {}).id || null,
    first_seen: Date.now(),
    checks_left: 60,
  };
}
return $input.all();

// Cover retry, riding on the listing this run already fetched - no extra request to the library.
// Emits a book only once the catalogue publishes its cover.
//
// Budget is 60 CHECKS, not 5 hours of wall clock. The opening-hours gate stops the workflow at
// 19:00 and all day Sunday, so a wall-clock window would expire overnight for any book added late
// in the day. A 7-day TTL is the backstop against a leak: a book that drops off the listing never
// spends its check budget.
const HARD_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const sd = $getWorkflowStaticData('global');
if (!sd.pendingCovers) { sd.pendingCovers = {}; }
const pending = sd.pendingCovers;
const now = Date.now();

for (const [k, r] of Object.entries(pending)) {
  if (!r || !r.first_seen || now - r.first_seen > HARD_TTL_MS) { delete pending[k]; }
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const rec = pending[j.link];
  if (!rec) { continue; }

  rec.checks_left = (rec.checks_left || 0) - 1;
  const budgetSpent = rec.checks_left <= 0;

  if (!j.img) {
    if (budgetSpent) { delete pending[j.link]; }
    continue;
  }

  // The entry is NOT dropped here. An edit is idempotent, so a failed attempt is safe to repeat;
  // only "Retry: sprzataj stan" removes the entry, and only after Telegram confirms the edit.
  // The budget still bounds the number of attempts.
  if (budgetSpent) { delete pending[j.link]; }
  out.push({ json: {
    link: j.link,
    img: j.img,
    message: j.message,
    chat_id: String(rec.chat_id),
    message_id: rec.message_id,
  } });
}
return out;

// Removes a pending entry only after Telegram confirms the edit. The catalog link is read back
// from the response caption_entities, so this does not depend on item pairing either.
const sd = $getWorkflowStaticData('global');
if (!sd.pendingCovers) { sd.pendingCovers = {}; }
const pending = sd.pendingCovers;

for (const item of $input.all()) {
  const res = item.json.result;
  if (!res) { continue; }
  const ents = res.caption_entities || res.entities || [];
  const ent = ents.find((e) => e.type === 'text_link' && /katalog\.wbp\.poznan\.pl/.test(e.url || ''));
  if (!ent) { continue; }
  delete pending[ent.url];
}
return $input.all();
